************************************************************************ Patch to Text Tools (ROM 01)** Copyright 1988-92 Apple Computer, Inc.* All Rights Reserved************************************************************************* 01 Aug 88	Steven Glass** Bug discovered in InitTextDev.  Was not returning error after* dispatching to device.** 20-Dec-90	Dave Lyons** Changed version to $8300 so we can match ROM 3 version for 6.0.** 5-Nov-91	Dave Lyons** Patched GetInputDevice, GetOutputDevice, GetErrorDevice to* pre-zero the result space for the device type, since the Set* calls do not tolerate the garbage in the high byte.  (Well,* at least the ROM 3 versions don't tolerate it.  So let's be* clean about the whole thing.)** Version is $8301.** 5-Feb-92	Dave Lyons** Version $0301 for 6.0 final.***********************************************************************	include 'all.macros'	include ':::sys.equs.asm'TextVersionNumber	equ $0301;-----------------------------------------------------------;; Equates for addresses in bank E1.;ANDin	equ $E115AAORin	equ ANDin+1ANDout	equ ORin+1ORout	equ ANDout+1ANDerr	equ ORout+1ORerr	equ ANDerr+1DevType	equ ORerr+1DevPtr	equ DevType+3InDevPtr	equ DevPtrOutDevPt	equ InDevPtr+4ErrDevPt	equ OutDevPt+4ErrHook	equ ErrDevPt+4*****************************************************************TTCallTable	PROC EXPORT** Contains the calls to patch in the text tools tool set.*** Inputs:*	none** Outputs:*	none** External Refs:	import InitTextDev	import TextVersion	import TextBootInit	import GetInDev	import GetOutDev	import GetErrDev** Entry Points:*	none*	longa on	; mode	longi on*****************************************************************Here	dc.L (TheEnd-Here)/4	; num calls +1	dc.L TextBootInit-1 ;$010C TextBootInit	dc.L 0	;$020C TextStartUp	dc.L 0	;$030C TextShutDown	dc.L TextVersion-1	;$040C TextVersion	dc.L 0 	;$050C TextReset	dc.L 0 	;$060C TextStatus	dc.L 0 	;$070C	dc.L 0 	;$080C	dc.L 0 	;$090C SetInGlobals	dc.L 0 	;$0A0C SetOutGlobals	dc.L 0 	;$0B0C SetErrorGlobals	dc.L 0 	;$0C0C GetInGlobals	dc.L 0 	;$0D0C GetOutGlobals	dc.L 0 	;$0E0C GetErrGlobals	dc.L 0 	;$0F0C SetInputDevice	dc.L 0 	;$100C SetOutputDevice	dc.L 0	;$110C SetErrorDevice	dc.L GetInDev-1	;$120C, patched 4-Nov-91 DAL	dc.L GetOutDev-1	;$130C, patched 4-Nov-91 DAL	dc.L GetErrDev-1	;$140C, patched 4-Nov-91 DAL	dc.L InitTextDev-1	;$150C InitTextDev	dc.L 0	;$160C CtlTextDev	dc.L 0	;$170C StatusTextDev	dc.L 0	;$180C WriteChar	dc.L 0	;$190C ErrWriteChar	dc.L 0	;$1A0C WriteLine	dc.L 0	;$1B0C ErrWriteLine	dc.L 0	;$1C0C WriteString	dc.L 0	;$1D0C ErroWriteString	dc.L 0	;$1E0C TextWriteBlock	dc.L 0	;$1F0C ErrWriteBlock	dc.L 0	;$200C WriteCString	dc.L 0	;$210C ErrWriteCString	dc.L 0	;$220C ReadChar	dc.L 0	;$230C TextReadBlock	dc.L 0	;$240C ReadLineTheEnd	ENDP*****************************************************************StdTextCalls	PROC** Contains the Version call and the boot init call*** Inputs:*	none** Outputs:*	none** External Refs:*	none** Entry Points:	ENTRY TextVersion	ENTRY TextBootInit*	longa on	; mode	longi on*****************************************************************TextVersion	lda #TextVersionNumber	sta 7,sTextBootInit	lda #0	clc	rtl	ENDP*****************************************************************InitTextDev	PROC** Init the specified text device.  Possible values are**	      0 = Input device*	      1 = Output device*	      2 = Error output device	  ** If the device is a basic device, the I/O hooks are set* to the init entry	for the device being called.** Inputs:*	Device to Init  : word** Outputs:*	none** External Refs:*	none** Entry Points:*	none*	longa on	; mode	longi on** Modification History:** 11 Sep 86    	Ray Montagne* Updated to handle save/restore of I/O hooks when initing an * error device.** 01 Aug 88    SEG      ** Added patch today to look for card firmware when using Basic * devices** 02 Aug 88    SEG      ** Made patch work correctly.  Also check for pascal devices.** 31 Oct 88    SEG** Check for valid input.*****************************************************************	DefineStackRTL1	block 3RTL2	block 3WhichDevice	wordIntoROM	equ $FEA8CC	lda WhichDevice,s	; use device as index into type array	cmp #3	; make sure input is valid  SEG 31 Oct 88	bcs BadDev	tax	lda >DevType,x	and #$00FF	cmp #2	; is it a ram driver?	beq Continue	; yes	txa	; no, make sure a ROM is switched in	asl a	; (use devtype as index into pointer array)	asl a	; (which holds slot number)	tax	lda >DevPtr,x	; read the slot number	and #$000F	; turn this into a Cn00 space	xba	ora #$C000	tax	sep #$20	longa off	ldy #10	lda >0,x	; read it once	beq BadDev	; cant be a BRKCheckFloatLoop	cmp >0,x	; read rom	bne BadDev	; if not same, then	no device	dey	bpl CheckFloatLoop	; check a bunch of times	rep #$20	longa onContinue	jml IntoROMBadDev	rep #$20	longa on	ldx #$0C01	ldy #2	jml ToStrip	ENDP****************************************************************** GetInDev, GetOutDev, GetErrDev** Patched 5-Nov-91 DAL to pre-zero the device-type output word.*****************************************************************GetInDev	proc export	lda #0	sta 11,s	jml >$fea89b	EndPGetOutDev	proc export	lda #0	sta 11,s	jml >$fea8c2	EndPGetErrDev	proc export	lda #0	sta 11,s	jml >$fea8c7	EndP	END